using System.Windows;
using SaarOSS.Rechnungsprogramm.Views;
namespace SaarOSS.Rechnungsprogramm;
public partial class MainWindow : Window { public MainWindow(){InitializeComponent();Navigate("Startseite",new DashboardView());} private void Navigate(string title,object view){PageTitle.Text=title;MainContent.Content=view;} private void ShowDashboard(object s,RoutedEventArgs e)=>Navigate("Startseite",new DashboardView()); private void ShowCustomers(object s,RoutedEventArgs e)=>Navigate("Kunden",new CustomersView()); private void ShowInvoices(object s,RoutedEventArgs e)=>Navigate("Rechnungen",new InvoicesView()); private void ShowOffers(object s,RoutedEventArgs e)=>Navigate("Angebote",new OffersView()); private void ShowSettings(object s,RoutedEventArgs e)=>Navigate("Einstellungen",new SettingsView()); private void ShowNumbering(object s,RoutedEventArgs e)=>Navigate("Nummernkreise",new NumberingView()); private void ShowAbout(object s,RoutedEventArgs e)=>Navigate("Über das Programm",new AboutView()); private void ShowUpdateCenter(object s,RoutedEventArgs e)=>Navigate("Update-Center",new UpdateCenterView()); private void NewInvoice(object s,RoutedEventArgs e)=>Navigate("Rechnungen",new InvoicesView()); }
